    /** A claim's due now: its figure, plus, while it is overdue (OPEN and its due-by — its date plus the
     *  sheet's terms — before the sheet's today), the sheet's late percent of that figure for every full
     *  30 days it is overdue, rounded to two decimals by the claim's rounding. A statement never binds the charge:
     *  it keeps following the sheet's today until settling freezes it in. A correction (a negative amount)
     *  has no late charge. Null when it has no figure. */
    public BigDecimal dueNow(String sheetId, Claim claim) {
        BigDecimal figure = figure(sheetId, claim);
        if (figure == null || !claim.status().equals("OPEN") || new BigDecimal(claim.amount()).signum() < 0) {
            return figure;
        }
        List<Object[]> found = jdbc.query("SELECT today, terms, late_pct FROM sheet WHERE id = ?",
                (rs, i) -> new Object[] { rs.getDate("today").toLocalDate(), rs.getInt("terms"),
                        rs.getBigDecimal("late_pct") }, sheetId);
        if (found.isEmpty()) return figure;
        LocalDate today = (LocalDate) found.get(0)[0];
        LocalDate dueBy = LocalDate.parse(claim.date()).plusDays((Integer) found.get(0)[1]);
        BigDecimal pct = (BigDecimal) found.get(0)[2];
        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
        if (periods == 0 || pct == null || pct.signum() == 0) return figure;
        BigDecimal charge = figure.multiply(pct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, rounding(sheetId, claim));
        return figure.add(charge);
    }

    /** Whether a rate for the grade the person has on a date is in force on that date. */
    public boolean rated(String sheetId, long personId, LocalDate on) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM rate r WHERE r.sheet_id = ? AND r.grade = " + GRADE_ON
                + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE))", Integer.class, sheetId,
                sheetId, personId, on.toString(), on.toString());
        return n != null && n > 0;
    }

    /** Bind a claim to a figure (stated), or unbind it (not stated, live again). */
    public void bind(String sheetId, long claimId, boolean stated, BigDecimal figure) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE id = ? AND sheet_id = ?", stated, figure,
                claimId, sheetId);
    }

    /** A person's claims on the sheet. */
    public List<Claim> ofPerson(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC",
                ROW, sheetId, personId);
    }

    /** Fix a settled claim's due. */
    public void settleDue(String sheetId, long claimId, BigDecimal due) {
        jdbc.update("UPDATE claim SET settled_due = ? WHERE id = ? AND sheet_id = ?", due, claimId, sheetId);
    }

    /** The name of a person on the sheet. */
    public String personName(String sheetId, long personId) {
        return jdbc.queryForObject("SELECT name FROM person WHERE sheet_id = ? AND id = ?",
                String.class, sheetId, personId);
    }

    /** Whether the person has a SETTLED claim with this number on the sheet. */
    public boolean settledOf(String sheetId, long personId, long number) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
                + " AND claim_no = ? AND status = 'SETTLED'", Integer.class, sheetId, personId, number);
        return n != null && n > 0;
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, Long corrects) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(c -> {
            PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects) VALUES (?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setObject(6, corrects);
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), personId, money(amount), date.toString(), note, "DRAFT", null, null, null, false, null, corrects);
    }

    /** Change a DRAFT claim's amount, date, note and the number it corrects; false when the sheet has no
     *  such draft claim. */
    public boolean update(String sheetId, long claimId, BigDecimal amount, LocalDate date, String note, Long corrects) {
        return jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ? WHERE id = ?"
                + " AND sheet_id = ? AND status = 'DRAFT'",
                amount, Date.valueOf(date), note, corrects, claimId, sheetId) > 0;
    }

    /** An amount as shown: two decimals, a dot, no grouping. */
    static String money(BigDecimal amount) {
        return amount.setScale(2).toPlainString();
    }

    /** A fixed due as shown, or null when there is none. */
    static String dueOf(BigDecimal due) {
        return due == null ? null : money(due);
    }
}
package net.officefloor.hq.app.claim;

/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
 *  (DRAFT, OPEN, SETTLED or VOID), its number on the sheet (null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
 *  (null until it is opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound with no figure: its due then stays live), and, for a correction (a negative
 *  amount), the number of the settled claim it corrects (null otherwise). */
public record Claim(long id, long personId, String amount, String date, String note, String status,
        Long number, String due, String openedBy, boolean stated, String statedDue, Long corrects) {

    /** Whether the claim counts toward claimed and every total: only OPEN and SETTLED claims do. */
    public boolean counts() {
        return status.equals("OPEN") || status.equals("SETTLED");
    }

    /** Whether the claim counts toward live totals (claimed, due-totals, a period's total) when its
     *  person is or is not on hold: a held person's OPEN claims do not; SETTLED claims always do. */
    public boolean counts(boolean held) {
        return status.equals("SETTLED") || (!held && status.equals("OPEN"));
    }

    /** The audit field a numbered claim adds at the end of its lines: " number=<n>", or "" when it has none. */
    static String auditNumber(Long number) {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** A claim's status change (open, settle or void), shared by the single and the bulk actions. Every
 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
final class ClaimStatusChange {
    private ClaimStatusChange() {
    }

    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
        String to;
        List<String> from;
        String event;
        switch (action == null ? "" : action.trim()) {
            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN"); event = "CLAIM_VOIDED"; }
            default -> throw new BadRequestException("no such action");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
        // Four eyes: whoever opened a claim cannot settle it.
        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
            throw new BadRequestException("the user who opened a claim cannot settle it");
        }
        // A clerk settles only a claim whose due is within the sheet's clerk limit ('n/a' is within any);
        // a steward settles anything.
        if (to.equals("SETTLED") && found.status().equals("OPEN")
                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
            BigDecimal limit = settings.clerkLimit(id);
            BigDecimal now = repository.dueNow(id, found);
            if (limit != null && now != null && now.compareTo(limit) > 0) {
                throw new BadRequestException("a clerk cannot settle a claim whose due is above the clerk limit of "
                        + SettingsRepository.money(limit));
            }
        }
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.changeStatus(id, cid, from, to)) {
            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
        }
        // Opening gives the sheet's next number; a voided claim keeps the number it had (never reused).
        Long number = found.number();
        String openedBy = found.openedBy();
        if (to.equals("OPEN")) {
            number = repository.number(id, cid);
            repository.openedBy(id, cid, by);
            openedBy = by;
        }
        // Settling fixes the claim's due as it is now: the figure its last statement bound it to, else its
        // live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
        String due = null;
        String settledDue = "";
        if (to.equals("SETTLED")) {
            BigDecimal now = repository.dueNow(id, found);
            repository.settleDue(id, cid, now);
            due = ClaimRepository.dueOf(now);
            settledDue = " due=" + (due == null ? "n/a" : due);
        }
        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
                number, due, openedBy, found.stated(), found.statedDue(), found.corrects());
        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + settledDue);
        rollup.record(id, by, before);
        return changed;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;

/** A validated claim form: the amount (negative for a correction), the date ({@code null} when left blank:
 *  the sheet's today), the note, and the number of the claim a correction corrects ({@code null} when left blank). */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, Long corrects) {

    private static final Pattern SIGNED = Pattern.compile("-?(\\d+(\\.\\d{1,2})?|\\.\\d{1,2})");

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?|\\.\\d{1,2}");

    /** A typed amount (trimmed): required, a number with up to two decimals, 0.00 or more. */
    public static BigDecimal amount(String amount) throws BadRequestException {
        if (amount.isEmpty()) {
            throw new BadRequestException("amount is required");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new BadRequestException("amount must be a number of 0.00 or more with up to two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** A typed claim-form amount (trimmed): required, a number with up to two decimals; a negative one
     *  is a correction. */
    public static BigDecimal signedAmount(String amount) throws BadRequestException {
        if (amount.isEmpty()) {
            throw new BadRequestException("amount is required");
        }
        if (!SIGNED.matcher(amount).matches()) {
            throw new BadRequestException("amount must be a number with up to two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** Whether the amount is a correction's: below zero. */
    public boolean correction() {
        return amount.signum() < 0;
    }

    /** Check the form against the person's claims: a negative amount must name, by number, a SETTLED
     *  claim of the same person; only a negative amount may name one. */
    public void checkCorrection(ClaimRepository repository, String sheetId, long personId) throws BadRequestException {
        if (!correction()) {
            if (corrects != null) {
                throw new BadRequestException("only a negative amount corrects a claim");
            }
            return;
        }
        if (corrects == null) {
            throw new BadRequestException("a negative amount is a correction: name the settled claim it corrects");
        }
        if (!repository.settledOf(sheetId, personId, corrects)) {
            throw new BadRequestException("claim " + corrects + " is not a settled claim of this person");
        }
    }
}
